package calc

import (
	"encoding/json"
	"fmt"
	"math/rand"
	"os"
	"testing"
	"time"
)

func huntDErr(err error) any {
	if err == nil {
		return nil
	}
	return err.Error()
}

func huntDRecord(name string, i int, input any, call func() any) {
	rec := map[string]any{"test": name, "i": i, "input": input}
	func() {
		defer func() {
			if r := recover(); r != nil {
				rec["panic"] = fmt.Sprint(r)
			}
		}()
		rec["output"] = call()
	}()
	line, err := json.Marshal(rec)
	if err != nil {
		line, _ = json.Marshal(map[string]any{"test": name, "i": i, "input": fmt.Sprintf("%#v", input), "panic": "unmarshalable: " + err.Error()})
	}
	out := os.Getenv("HUNT_DIFF_OUT")
	if out == "" {
		return
	}
	f, ferr := os.OpenFile(out, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if ferr != nil {
		panic(ferr)
	}
	defer f.Close()
	_, _ = f.Write(append(line, '\n'))
}

func TestHuntD_ScaleAt(t *testing.T) {
	r := rand.New(rand.NewSource(1))
	for i := 0; i < 200; i++ {
		v := r.Intn(2000) - 1000
		huntDRecord("TestHuntD_ScaleAt", i, v, func() any { return map[string]any{"v": Scale(v), "at": time.Now().UnixNano()} })
	}
}
